public final class StatsActivity extends WorkspaceActivity {
    private static final java.util.concurrent.atomic.AtomicBoolean exporting=new java.util.concurrent.atomic.AtomicBoolean();
    private final android.os.Handler statusHandler=new android.os.Handler(android.os.Looper.getMainLooper());
    private Dialog librarySheet;private boolean feesTab;private boolean achievements;private String achievementDetail="";private int statsScroll;
    private TextView exportStatus;private ScrollView page;private int restoredScroll;
    private final Runnable pollStatus=new Runnable(){public void run(){refreshExportStatus();if(exporting.get())statusHandler.postDelayed(this,500);}};
    private android.content.SharedPreferences exportPrefs(){return getSharedPreferences("annual-export",0);}
    private void refreshExportStatus(){if(exportStatus!=null){String status=exportPrefs().getString("status","");exportStatus.setText(status);exportStatus.setVisibility(status.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);}}
    private final Set<String> expandedRanks=new HashSet<>();
    private LogStore logs;private LinearLayout root,body;private boolean archived=true;private int year,exportYear,weekSelected=6;private boolean exportArchived;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);logs=new LogStore(this);if(exportPrefs().getBoolean("pending",false)&&!exporting.get())exportPrefs().edit().putBoolean("pending",false).putString("status","上次年度导出被中断，目标可能有不完整文件，请重新保存。").commit();if(saved!=null){achievements=saved.getBoolean("achievements");feesTab=saved.getBoolean("feesTab");achievementDetail=saved.getString("achievementDetail","");statsScroll=saved.getInt("statsScroll");restoredScroll=saved.getInt("scrollY");ArrayList<String> expanded=saved.getStringArrayList("expandedRanks");if(expanded!=null)expandedRanks.addAll(expanded);year=saved.getInt("year");weekSelected=Math.max(0,Math.min(6,saved.getInt("weekSelected",6)));archived=saved.getBoolean("archived",true);exportYear=saved.getInt("exportYear");exportArchived=saved.getBoolean("exportArchived");}render();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(UiColors.color(getResources(),0xfff2eadf));t.setTextSize(size);t.setPadding(0,dp(6),0,dp(6));return t;}
    private Button button(String value,Runnable action){return LibraryUi.action(this,value,false,action);}
    private void render(){if(achievements){renderAchievements();return;}StatsStore.Summary summary=StatsStore.read(logs,feesTab?0:year,archived);root=column();root.setBackgroundColor(getColor(R.color.ui_background));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();root.addView(LibraryUi.header(this,"统计与回顾",this::finish,LibraryUi.icon(this,0xe1fe,"更多统计",()->new AlertDialog.Builder(this).setTitle("统计与回顾").setItems(new String[]{"选择回顾年份","统计说明","成就"},(d,w)->{if(w==0){chooseYear(StatsStore.read(logs,0,archived));}else if(w==1)statisticsInfo(summary);else openAchievements();}).show())));
        LinearLayout pane=column();pane.setPadding(dp(16),0,dp(16),0);root.addView(pane,new LinearLayout.LayoutParams(-1,0,1));pane.addView(LibraryUi.tabs(this,new String[]{"拍摄","费用"},feesTab?1:0,n->{feesTab=n==1;restoredScroll=0;render();}));LinearLayout filters=new LinearLayout(this);Button yearButton=button(feesTab?"累计费用":year==0?"全部年份 ▾":year+" 年 ▾",()->{if(!feesTab)chooseYear(summary);});yearButton.setBackgroundColor(Color.TRANSPARENT);filters.addView(yearButton,new LinearLayout.LayoutParams(0,-2,1));Button scope=button(archived?"含归档":"不含归档",()->{archived=!archived;restoredScroll=0;render();});scope.setBackgroundColor(Color.TRANSPARENT);filters.addView(scope);pane.addView(filters);exportStatus=text("",12);pane.addView(exportStatus);refreshExportStatus();ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);page=scroll;final int y=restoredScroll;restoredScroll=0;scroll.post(()->scroll.scrollTo(0,y));body=column();body.setPadding(0,dp(8),0,dp(24));scroll.addView(body);pane.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(feesTab){fees(summary);return;}LinearLayout hero=new LinearLayout(this);for(int i=0;i<2;i++){LinearLayout stat=column();TextView number=text((i==0?summary.frames:summary.rolls)+(i==0?" 张":" 卷"),i==0?36:28);number.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);stat.addView(number);TextView caption=text(i==0?"曝光记录":year==0?"胶卷 · 含空卷":"当年有曝光的胶卷",12);caption.setTextColor(getColor(R.color.ui_muted));stat.addView(caption);hero.addView(stat,new LinearLayout.LayoutParams(0,-2,1));}body.addView(hero);TextView inline=text(summary.days+" 个拍摄日期 · "+summary.stockRolls.size()+" 种胶片 · "+summary.cameraRolls.size()+" 台相机",12);inline.setTextColor(getColor(R.color.ui_muted));body.addView(inline);if(year==0||year==java.time.LocalDate.now().getYear())weeklyActivity(summary);monthChart(summary);ranking("常用胶片",summary.stockRolls,null,"卷",0);body.addView(new android.view.View(this),new LinearLayout.LayoutParams(1,dp(12)));body.addView(button(year==0?"选择年份，查看年度回顾":"保存 "+year+" 年度回顾",()->{if(year==0)chooseYear(summary);else exportPoster();}));body.addView(new android.view.View(this),new LinearLayout.LayoutParams(1,dp(12)));body.addView(button("更多统计与统计说明",()->statisticsInfo(summary)));}
    private void fees(StatsStore.Summary summary){TextView note=text("按已填写金额累计。费用没有发生日期，不按拍摄年份推算年度支出。",12);note.setTextColor(getColor(R.color.ui_muted));body.addView(note);if(summary.budgets.isEmpty())body.addView(text("还没有已记录费用",20));for(Map.Entry<String,StatsStore.Budget> entry:summary.budgets.entrySet()){StatsStore.Budget b=entry.getValue();LinearLayout card=column();card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(LibraryUi.surface(this,getColor(R.color.ui_card),10));card.addView(text("已记录支出 · "+entry.getKey(),12));TextView total=text(entry.getKey()+" "+b.recorded.toPlainString(),28);total.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);card.addView(total);card.addView(text("胶片 "+b.film.toPlainString()+" · 冲洗 "+b.lab.toPlainString(),12));if(b.frames>0)card.addView(text("每张 "+b.complete.divide(java.math.BigDecimal.valueOf(b.frames),2,RoundingMode.HALF_UP).toPlainString()+" · 仅含两项费用均填写的胶卷",11));LinearLayout.LayoutParams gap=new LinearLayout.LayoutParams(-1,-2);gap.topMargin=dp(12);body.addView(card,gap);}body.addView(text(summary.missingCostRolls+" 卷有费用未填写，"+summary.unknownCurrencyRolls+" 卷未指定币种。空白表示未知，0 表示已确认无费用。不同币种分别统计。",12));body.addView(button("查看费用明细",()->{LinearLayout details=column();details.setPadding(dp(16),0,dp(16),dp(16));CatalogStore catalog=new CatalogStore(logs);for(LogStore.Roll r:logs.rolls()){CatalogStore.Detail metadata=catalog.detail(r.id);if(metadata!=null&&metadata.returned||!archived&&(r.archived||r.state.equals("received")))continue;LibraryUi.fact(this,details,r.name,"胶片 "+(r.filmCost.isEmpty()?"未填":r.filmCost)+" · 冲洗 "+(r.labCost.isEmpty()?"未填":r.labCost)+" "+r.currency);}librarySheet=LibraryUi.sheet(this,"费用明细",details,null);}));}
    private void statisticsInfo(StatsStore.Summary summary){LinearLayout details=column();details.setPadding(dp(16),0,dp(16),dp(16));LibraryUi.fact(this,details,"平均每卷",summary.perRoll()+" 张");LibraryUi.fact(this,details,"已定位",summary.located+" 张");LibraryUi.fact(this,details,"已关联扫描",summary.scanned+" 张");LibraryUi.fact(this,details,"最长连续拍摄",summary.longestStreak+" 天");if(!summary.firstDate.isEmpty())LibraryUi.fact(this,details,"拍摄日期",summary.firstDate+" 至 "+summary.lastDate);details.addView(text("按曝光保存的时区与修改后的拍摄日期统计。全部年份包含空卷；年度卷数只计当年有曝光的胶卷。返还库存的空卷不计入。费用按币种累计，不推算年度费用。",12));details.addView(button("查看成就",()->{if(librarySheet!=null)librarySheet.dismiss();openAchievements();}));librarySheet=LibraryUi.sheet(this,"更多统计与统计说明",details,null);}
    private void monthChart(StatsStore.Summary summary){body.addView(text(year==0?"各月累计 · 跨年合计":"每月拍摄 · "+year+" 年",16));LinearLayout chart=new LinearLayout(this);int max=1;for(int n:summary.months)max=Math.max(max,n);final int peak=max;for(int i=0;i<12;i++){final int index=i;LinearLayout cell=column();cell.setGravity(android.view.Gravity.CENTER_HORIZONTAL);android.view.View bar=new android.view.View(this){private final android.graphics.Paint p=new android.graphics.Paint();@Override protected void onDraw(android.graphics.Canvas c){p.setColor(getColor(R.color.ui_accent));float h=summary.months[index]==0?1:Math.max(dp(2),getHeight()*(float)summary.months[index]/peak);c.drawRect(dp(3),getHeight()-h,getWidth()-dp(3),getHeight(),p);}};cell.addView(bar,new LinearLayout.LayoutParams(-1,dp(64)));TextView month=text(String.valueOf(i+1),10);month.setGravity(android.view.Gravity.CENTER);cell.addView(month);cell.setContentDescription((i+1)+"月，"+summary.months[i]+"张曝光");cell.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_YES);chart.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}body.addView(chart);}
    private void exportPoster(){if(exporting.get()){Toast.makeText(this,"年度图片正在保存，请稍候",1).show();return;}exportYear=year;exportArchived=archived;android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_CREATE_DOCUMENT).addCategory(android.content.Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(android.content.Intent.EXTRA_TITLE,"胶片随记-"+year+"-年度回顾.png");try{startActivityForResult(intent,1);}catch(android.content.ActivityNotFoundException e){Toast.makeText(this,"没有可用的文件保存器",1).show();}}
    private void openAchievements(){statsScroll=page==null?0:page.getScrollY();restoredScroll=0;achievements=true;render();}
    private void closeAchievements(){achievements=false;achievementDetail="";restoredScroll=statsScroll;render();}
    private android.graphics.drawable.GradientDrawable achievementSurface(){android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(UiColors.color(getResources(),0xff30251e));bg.setCornerRadius(dp(14));return bg;}
    private TextView achievementIcon(int code,int size){TextView icon=text(String.valueOf((char)code),size);icon.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,size);icon.setTypeface(android.graphics.Typeface.createFromAsset(getAssets(),"fonts/Phosphor.ttf"));icon.setPadding(0,0,0,0);icon.setGravity(android.view.Gravity.CENTER);icon.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);return icon;}
    private String achievementName(AchievementProgress data,AchievementProgress.Item item){return item.secret()?data.label("achievementSecretName"):item.name;}
    private String achievementStatus(AchievementProgress.Item item){return item.progress<0?"待核验":item.reached()?"本地达成":Math.min(item.progress,item.target)+" / "+item.target;}
    private String rarityWord(AchievementProgress data,AchievementProgress.Item item){return item.rarity.equals("common")?"":data.label("achievementRarity"+Character.toUpperCase(item.rarity.charAt(0))+item.rarity.substring(1));}
    private void renderAchievements(){
        exportStatus=null;AchievementProgress data=new AchievementProgress(this,logs);root=column();root.setBackgroundColor(UiColors.color(getResources(),0xff1f1612));root.setClipToPadding(false);root.setPadding(dp(16),0,dp(16),0);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16)+i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),dp(16)+i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
        root.addView(LibraryUi.header(this,data.label("achievementsTitle"),this::closeAchievements,null,16));
        ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);page=scroll;final int y=restoredScroll;restoredScroll=0;scroll.post(()->scroll.scrollTo(0,y));body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(text(data.reached()+" 项本地达成 · 19 项成就",22));body.addView(text("按本地现存记录计算；原账号徽章和使用年限待核验。",13));
        for(Map.Entry<String,String> group:data.groups.entrySet()){body.addView(text(group.getValue(),18));LinearLayout card=column();card.setBackground(achievementSurface());body.addView(card);for(AchievementProgress.Item item:data.items){if(!item.group.equals(group.getKey()))continue;if(card.getChildCount()>0){android.view.View divider=new android.view.View(this);divider.setBackgroundColor(UiColors.color(getResources(),0xff49372b));LinearLayout.LayoutParams line=new LinearLayout.LayoutParams(-1,dp(1));line.leftMargin=dp(64);card.addView(divider,line);}LinearLayout row=new LinearLayout(this);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(10),dp(8),dp(10));TextView icon=achievementIcon(item.secret()?0xe3e8:item.icon,25);icon.setTextColor(item.reached()?UiColors.color(getResources(),0xffef8249):UiColors.color(getResources(),0xffb4a99f));row.addView(icon,new LinearLayout.LayoutParams(dp(40),dp(44)));LinearLayout words=column();String name=achievementName(data,item);TextView heading=text(name,17);heading.setPadding(dp(8),0,dp(8),dp(3));words.addView(heading);TextView condition=text(item.secret()?data.label("achievementSecretHint"):item.condition,13);condition.setPadding(dp(8),0,dp(8),dp(3));condition.setTextColor(UiColors.color(getResources(),0xffb4a99f));words.addView(condition);String rarity=rarityWord(data,item);TextView progress=text((rarity.isEmpty()?"":rarity+" · ")+achievementStatus(item),12);progress.setPadding(dp(8),0,dp(8),0);words.addView(progress);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=achievementIcon(0xe13a,18);row.addView(arrow,new LinearLayout.LayoutParams(dp(32),dp(44)));row.setFocusable(true);row.setContentDescription(name+"，"+condition.getText()+"，"+achievementStatus(item)+"，查看详情");row.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_YES);words.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);row.setOnClickListener(v->showAchievement(data,item));card.addView(row);}}
        if(!achievementDetail.isEmpty())for(AchievementProgress.Item item:data.items)if(item.id.equals(achievementDetail)){showAchievement(data,item);break;}
    }
    private void showAchievement(AchievementProgress data,AchievementProgress.Item item){
        achievementDetail=item.id;LinearLayout content=column();content.setPadding(dp(20),dp(16),dp(20),dp(12));content.addView(achievementIcon(item.secret()?0xe3e8:item.icon,48));TextView title=text(achievementName(data,item),24);title.setGravity(android.view.Gravity.CENTER);content.addView(title);String rarity=rarityWord(data,item);content.addView(text((rarity.isEmpty()?"":rarity+" · ")+achievementStatus(item),14));content.addView(text(item.secret()?data.label("achievementSecretHint"):item.condition,18));content.addView(text(item.secret()?data.label("achievementSecretDescription"):item.description,15));
        if(item.progress>=0&&!item.secret()){ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(item.target);progress.setProgress(Math.min(item.progress,item.target));progress.setContentDescription(achievementStatus(item));content.addView(progress);}String explanation=item.progress<0?"本机没有可核验的原账号创建日期，不能由安装时间或照片日期推算。":item.metric.equals("streak")?"按现存曝光的拍摄日期计算历史最长连续天数；不推断原账号授勋历史。":item.metric.equals("goldenHourShots")?"按记录时区的 06:00–08:00 前、17:00–19:00 前统计；沿用原版固定时段。":item.metric.equals("seasons")?"按记录时区月份分冬（12–2）、春（3–5）、夏（6–8）、秋（9–11），跨年合并。":item.metric.equals("cameras")?"按器材目录中的相机数量计算，含已归档器材；胶卷快照里的相机名称不增加器材数。":item.metric.equals("bwShots")?"按原片种工艺及原版未知名称关键词识别，未知名称不凭封面猜测。":"按本地现存胶卷与曝光计算，含归档；已撤销并返还库存的空卷除外。";content.addView(text(explanation,13));ScrollView scroll=new ScrollView(this);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(this).setView(scroll).setPositiveButton("关闭",null).create();dialog.setOnDismissListener(d->achievementDetail="");dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setGravity(android.view.Gravity.BOTTOM);dialog.getWindow().setLayout(-1,-2);}
    }
    @Override public void onBackPressed(){if(achievements)closeAchievements();else super.onBackPressed();}
    private void weeklyActivity(StatsStore.Summary summary){
        body.addView(text("近期拍摄",16));TextView caption=text("",12);body.addView(caption);
        LinearLayout week=new LinearLayout(this);LinearLayout[] cells=new LinearLayout[7];TextView[] labels=new TextView[7];android.view.View[] bars=new android.view.View[7];
        int maximum=0;for(int value:summary.week)maximum=Math.max(maximum,value);final int peak=maximum;
        Runnable select=()->{
            caption.setText((weekSelected==6?"本周":(6-weekSelected)+" 周前")+" "+summary.week[weekSelected]+" 张 · 按拍摄日期");
            for(int n=0;n<7;n++){boolean selected=n==weekSelected;cells[n].setSelected(selected);labels[n].setTextColor(selected?UiColors.color(getResources(),0xfff07f4a):UiColors.color(getResources(),0xfff4eee2));labels[n].setTypeface(android.graphics.Typeface.create("monospace",selected?android.graphics.Typeface.BOLD:android.graphics.Typeface.NORMAL));bars[n].invalidate();}
        };
        for(int i=0;i<7;i++){
            final int index=i;LinearLayout cell=column();cell.setGravity(android.view.Gravity.CENTER_HORIZONTAL);cell.setFocusable(true);cell.setClickable(true);
            cell.setAccessibilityDelegate(new android.view.View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(android.view.View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(Button.class.getName());}});
            cell.setContentDescription((i==6?"本周":(6-i)+"周前")+"，"+summary.week[i]+"张曝光");cells[i]=cell;
            android.view.View bar=new android.view.View(this){
                private final android.graphics.Paint paint=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);
                private final android.graphics.Path path=new android.graphics.Path();
                @Override protected void onDraw(android.graphics.Canvas canvas){
                    super.onDraw(canvas);float fraction=peak==0?.03f:Math.max(.03f,(float)summary.week[index]/peak);float top=getHeight()*(1-fraction);float radius=dp(4);
                    // shortcut: retain the current stats ink until the original theme color is verified.
                    paint.setColor(index==weekSelected?UiColors.color(getResources(),0xfff07f4a):(index==6?UiColors.color(getResources(),0x73f4eee2):UiColors.color(getResources(),0x33f4eee2)));path.reset();
                    path.addRoundRect(new android.graphics.RectF(0,top,getWidth(),getHeight()),new float[]{radius,radius,radius,radius,0,0,0,0},android.graphics.Path.Direction.CW);canvas.drawPath(path,paint);
                }
            };
            bar.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);bars[i]=bar;
            LinearLayout.LayoutParams plot=new LinearLayout.LayoutParams(-1,dp(80));plot.leftMargin=dp(5);plot.rightMargin=dp(5);cell.addView(bar,plot);
            TextView label=text(i==6?"本周":(6-i)+" 周前",11);label.setPadding(0,dp(6),0,0);label.setGravity(android.view.Gravity.CENTER);label.setSingleLine(true);label.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);labels[i]=label;cell.addView(label,new LinearLayout.LayoutParams(-1,-2));
            cell.setOnClickListener(v->{weekSelected=index;v.performHapticFeedback(android.view.HapticFeedbackConstants.CLOCK_TICK);select.run();});week.addView(cell,new LinearLayout.LayoutParams(0,-2,1));
        }
        select.run();body.addView(week);
    }

    private android.graphics.drawable.GradientDrawable panel(){android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(UiColors.color(getResources(),0xff17100c));shape.setCornerRadius(dp(18));shape.setStroke(dp(1),UiColors.color(getResources(),0x21e8906a));return shape;}
    private void figures(StatsStore.Summary summary){
        ArrayList<String> labels=new ArrayList<>(Arrays.asList("张","卷","张 / 卷","种胶片"));
        ArrayList<String> values=new ArrayList<>(Arrays.asList(""+summary.frames,""+summary.rolls,""+summary.perRoll(),""+summary.stockRolls.size()));
        if(!summary.cameraRolls.isEmpty()){labels.add("台相机");values.add(""+summary.cameraRolls.size());}if(!summary.lenses.isEmpty()){labels.add("支镜头");values.add(""+summary.lenses.size());}
        LinearLayout grid=new LinearLayout(this){int priorColumns;
            @Override protected void onMeasure(int width,int height){
                float scale=getResources().getConfiguration().fontScale;int available=android.view.View.MeasureSpec.getSize(width);
                // shortcut: 104dp minimum column width is local; replace when the original width constant is recovered.
                int columns=Math.max(1,Math.min(labels.size(),(int)(available/(dp(104)*scale))));
                if(columns!=priorColumns){priorColumns=columns;removeAllViews();
                    for(int first=0;first<labels.size();first+=columns){if(first>0){android.view.View line=new android.view.View(StatsActivity.this);line.setBackgroundColor(UiColors.color(getResources(),0x21e8906a));addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}LinearLayout row=new LinearLayout(StatsActivity.this);row.setGravity(android.view.Gravity.TOP);addView(row,new LinearLayout.LayoutParams(-1,-2));
                        for(int col=0;col<columns;col++){if(col>0){android.view.View line=new android.view.View(StatsActivity.this);line.setBackgroundColor(UiColors.color(getResources(),0x21e8906a));row.addView(line,new LinearLayout.LayoutParams(dp(1),-1));}int index=first+col;LinearLayout cell=column();cell.setGravity(android.view.Gravity.CENTER_HORIZONTAL);cell.setPadding(dp(12),dp(14),dp(12),dp(14));row.addView(cell,new LinearLayout.LayoutParams(0,-2,1));if(index>=labels.size())continue;
                            TextView number=text(values.get(index),24);number.setPadding(0,0,0,0);number.setIncludeFontPadding(false);number.setTypeface(android.os.Build.VERSION.SDK_INT>=28?android.graphics.Typeface.create(android.graphics.Typeface.MONOSPACE,500,false):android.graphics.Typeface.MONOSPACE);number.setFontFeatureSettings("tnum");number.setGravity(android.view.Gravity.CENTER);cell.addView(number);
                            TextView label=text(labels.get(index),13);label.setTextColor(UiColors.color(getResources(),0xff9e948c));label.setPadding(0,dp(2),0,0);label.setGravity(android.view.Gravity.CENTER);label.setSingleLine(true);float sp=getResources().getDisplayMetrics().scaledDensity;label.setAutoSizeTextTypeUniformWithPresetSizes(new int[]{Math.round(11*sp),Math.round(11.5f*sp),Math.round(12*sp),Math.round(12.5f*sp),Math.round(13*sp)},android.util.TypedValue.COMPLEX_UNIT_PX);cell.addView(label,new LinearLayout.LayoutParams(-1,-2));
                            cell.setContentDescription(values.get(index)+" "+labels.get(index));cell.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_YES);number.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);label.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                        }
                    }
                }super.onMeasure(width,height);
            }
        };grid.setOrientation(1);grid.setBackground(panel());grid.setClipToOutline(true);LinearLayout.LayoutParams spacing=new LinearLayout.LayoutParams(-1,-2);spacing.topMargin=spacing.bottomMargin=dp(8);body.addView(grid,spacing);
    }
    private void ranking(String title,Map<String,Integer> values,Map<String,Integer> exposures,String unit,int collapsedCount){
        body.addView(text(title,20));ArrayList<Map.Entry<String,Integer>> sorted=new ArrayList<>(values.entrySet());sorted.sort(Comparator.<Map.Entry<String,Integer>>comparingInt(Map.Entry::getValue).reversed().thenComparing(Comparator.comparingInt((Map.Entry<String,Integer> e)->exposures==null?0:exposures.getOrDefault(e.getKey(),0)).reversed()).thenComparing(Map.Entry::getKey));
        LinearLayout group=column();group.setBackground(panel());body.addView(group);ArrayList<android.view.View> rows=new ArrayList<>();
        for(Map.Entry<String,Integer> entry:sorted){LinearLayout row=new LinearLayout(this);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(46));row.setPadding(dp(14),dp(9),dp(14),dp(9));LinearLayout words=column();TextView name=text(entry.getKey(),15);name.setLetterSpacing(-.23f/15);name.setPadding(0,0,0,0);words.addView(name);if(exposures!=null){TextView detail=text(exposures.getOrDefault(entry.getKey(),0)+" 张",13);detail.setTextColor(UiColors.color(getResources(),0xffbfb3a6));detail.setLetterSpacing(-.08f/13);detail.setPadding(0,dp(2),0,0);words.addView(detail);}row.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView value=text(entry.getValue()+" "+unit,15);value.setPadding(dp(12),0,0,0);value.setTypeface(android.graphics.Typeface.MONOSPACE);row.addView(value);group.addView(row);rows.add(row);}
        if(sorted.isEmpty())group.addView(text("暂无记录",14));
        if(collapsedCount>0&&sorted.size()>collapsedCount){Button toggle=button("",()->{});toggle.setBackgroundColor(Color.TRANSPARENT);body.addView(toggle);Runnable update=()->{boolean expanded=expandedRanks.contains(title);for(int i=0;i<rows.size();i++)rows.get(i).setVisibility(expanded||i<collapsedCount?android.view.View.VISIBLE:android.view.View.GONE);toggle.setText(expanded?"收起":"查看其余 "+(sorted.size()-collapsedCount)+" 项");toggle.setContentDescription(title+"，"+toggle.getText());};toggle.setOnClickListener(v->{if(!expandedRanks.remove(title))expandedRanks.add(title);update.run();});update.run();}
    }
    private void chooseYear(StatsStore.Summary summary){ArrayList<Integer> years=new ArrayList<>();years.add(0);years.addAll(summary.years);String[] labels=new String[years.size()];for(int i=0;i<labels.length;i++)labels[i]=years.get(i)==0?"全部年份":years.get(i)+" 年";new AlertDialog.Builder(this).setTitle("统计年份").setItems(labels,(d,w)->{year=years.get(w);feesTab=false;restoredScroll=0;render();}).show();}
    @Override protected void onActivityResult(int request,int result,android.content.Intent data){
        super.onActivityResult(request,result,data);if(request!=1||result!=RESULT_OK||data==null||data.getData()==null)return;
        if(!exporting.compareAndSet(false,true)){Toast.makeText(this,"已有年度图片正在保存，本次目标未写入",1).show();return;}
        final android.net.Uri uri=data.getData();final int selectedYear=exportYear;final boolean includeArchived=exportArchived;final android.content.Context app=getApplicationContext();
        if(!exportPrefs().edit().putBoolean("pending",true).putString("status","正在保存年度图片…").commit()){exporting.set(false);Toast.makeText(this,"无法保存导出状态，请重试",1).show();return;}
        statusHandler.removeCallbacks(pollStatus);statusHandler.post(pollStatus);
        new Thread(()->{String message;try(LogStore store=new LogStore(app);java.io.OutputStream out=app.getContentResolver().openOutputStream(uri,"wt")){
            if(out==null)throw new java.io.IOException("无法写入");StatsPoster.write(StatsStore.read(store,selectedYear,includeArchived),includeArchived,out);out.flush();message="年度回顾图片已保存";
        }catch(Exception error){message="保存失败，目标可能有不完整文件："+error.getMessage();}
        app.getSharedPreferences("annual-export",0).edit().putBoolean("pending",false).putString("status",message).commit();exporting.set(false);
        final String done=message;new android.os.Handler(android.os.Looper.getMainLooper()).post(()->Toast.makeText(app,done,1).show());
        },"year-poster").start();
    }
    @Override protected void onResume(){super.onResume();statusHandler.removeCallbacks(pollStatus);statusHandler.post(pollStatus);}
    @Override protected void onPause(){statusHandler.removeCallbacks(pollStatus);super.onPause();}
    @Override protected void onSaveInstanceState(Bundle out){out.putBoolean("feesTab",feesTab);out.putBoolean("achievements",achievements);out.putString("achievementDetail",achievementDetail);out.putInt("statsScroll",statsScroll);out.putInt("scrollY",page==null?0:page.getScrollY());out.putStringArrayList("expandedRanks",new ArrayList<>(expandedRanks));out.putInt("year",year);out.putInt("weekSelected",weekSelected);out.putBoolean("archived",archived);out.putInt("exportYear",exportYear);out.putBoolean("exportArchived",exportArchived);super.onSaveInstanceState(out);}
    @Override protected void onDestroy(){if(librarySheet!=null)librarySheet.dismiss();logs.close();super.onDestroy();}
}
